def gen(rng):
    def fmt(n, rels):
        return str(n) + ' ' + str(len(rels)) + ('\n' if rels else '') + '\n'.join('%d %s %d' % r for r in rels)
    def write(a, b):
        # a taller than b, written in a random direction
        return (a, '>', b) if rng.random() < 0.5 else (b, '<', a)
    def chain(n, extra, drop=0, cycle=False):
        perm = list(range(n))
        rng.shuffle(perm)
        rels = [write(perm[i], perm[i + 1]) for i in range(n - 1)]
        for _ in range(extra):
            if n >= 2:
                i = rng.randint(0, n - 2)
                j = rng.randint(i + 1, n - 1)
                rels.append(write(perm[i], perm[j]))
        for _ in range(drop):
            if rels:
                rels.pop(rng.randrange(len(rels)))
        if cycle and n >= 2:
            i = rng.randint(0, n - 2)
            j = rng.randint(i + 1, n - 1)
            rels.append(write(perm[j], perm[i]))
        rng.shuffle(rels)
        return rels
    tests = [
        fmt(1, []),
        fmt(2, []),
        fmt(2, [(0, '>', 1)]),
        fmt(2, [(0, '>', 1), (1, '>', 0)]),
        fmt(3, [(0, '>', 1), (2, '<', 1)]),
        fmt(3, [(0, '>', 1), (0, '>', 2)]),
        fmt(3, [(0, '>', 1), (1, '>', 2), (2, '>', 0)]),
        fmt(4, [(0, '>', 1), (1, '>', 2)]),
        fmt(3, [(0, '>', 1), (0, '>', 1), (1, '>', 2)]),
    ]
    for _ in range(60):
        n = rng.randint(1, 7)
        kind = rng.randint(0, 3)
        if kind == 0:
            rels = chain(n, rng.randint(0, 4))
        elif kind == 1:
            rels = chain(n, rng.randint(0, 4), drop=1)
        elif kind == 2:
            rels = chain(n, rng.randint(0, 3), cycle=True)
        else:
            rels = [write(*rng.sample(range(n), 2)) for _ in range(rng.randint(0, 9))] if n >= 2 else []
        tests.append(fmt(n, rels))
    N = 100000
    tests.append(fmt(N, chain(N, 1)))
    tests.append(fmt(N, chain(N, 1, drop=1)))
    tests.append(fmt(N, chain(N, 0, cycle=True)))
    tests.append(fmt(N, chain(N, 0)))
    return tests

